  if(!p.landed){p.x+=(wind*p.sp+14*Math.sin(t*1.3+p.ph))*dt;p.y+=(p.vy+10*Math.sin(t*1.7+p.ph*2))*dt;if(p.y>=p.wy){p.landed=true;p.y=p.wy}}
